for(let i=0;i<2;i++){const controller=renderer.xr.getController(i);rig.add(controller);const line=new THREE.Line(new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(),new THREE.Vector3(0,0,-1)]),new THREE.LineBasicMaterial({color:'#9de8dd'}));line.scale.z=6;controller.add(line);controller.addEventListener('squeezestart',()=>{const g=mode==='brain'?brain:molecule;g.scale.setScalar(g.scale.x>1.2?.8:g.scale.x+.3);});controller.addEventListener('selectstart',()=>{const rot=new THREE.Matrix4().extractRotation(controller.matrixWorld);ray.ray.origin.setFromMatrixPosition(controller.matrixWorld);ray.ray.direction.set(0,0,-1).applyMatrix4(rot);const hits=ray.intersectObjects([...vrButtons,...(mode==='brain'?parcels.filter(mesh=>mesh.visible):[])],false);if(!hits.length)return;const obj=hits[0].object;if(obj.userData.action)obj.userData.action();else if(selected===obj)enterProtein();else chooseRegion(obj,false);});}
const vrButton=VRButton.createButton(renderer);document.body.append(vrButton);renderer.xr.addEventListener('sessionstart',()=>{if(busy)returnBrain();vrUI.visible=true;tween=null;for(const mesh of parcels)mesh.visible=true;updateVRLabel();controls.enabled=false;rig.position.set(0,0,2.8);camera.position.set(0,0,0);camera.clearViewOffset();$('hover').hidden=true;});renderer.xr.addEventListener('sessionend',()=>{vrUI.visible=false;controls.enabled=true;rig.position.set(0,0,0);resize();if(mode==='brain')restoreCortexView();else camera.position.copy(defaultCamera());});
async function init(){
 try{
  const [atlas,p,expression,ranking]=await Promise.all([fetch('assets/brain.json').then(r=>{if(!r.ok)throw Error('Brain asset unavailable');return r.json();}),fetch('assets/proteins.json').then(r=>r.json()),fetch('assets/expression.json').then(r=>{if(!r.ok)throw Error('Expression evidence unavailable');return r.json();}),fetch('assets/regional-ranking.json').then(r=>{if(!r.ok)throw Error('Regional ranking evidence unavailable');return r.json();})]);
  if(atlas.version!==2)throw Error('Brain data format is outdated. Refresh this page.');
  const response=await fetch('assets/'+atlas.binary);if(!response.ok)throw Error('Anatomical surface unavailable');const binary=await response.arrayBuffer();
  manifest=p;const all=new THREE.Box3();
  const atlasToWorld=new THREE.Matrix4().makeRotationX(-Math.PI/2).scale(new THREE.Vector3(.009,.009,.009));
  for(const part of atlas.regions){
   const geometry=new THREE.BufferGeometry();
   geometry.setAttribute('position',new THREE.BufferAttribute(new Float32Array(binary,part.positionOffset,part.vertexCount*3),3));
   geometry.setAttribute('normal',new THREE.BufferAttribute(new Float32Array(binary,part.normalOffset,part.vertexCount*3),3));
   geometry.setIndex(new THREE.BufferAttribute(new Uint32Array(binary,part.indexOffset,part.indexCount),1));
   geometry.applyMatrix4(atlasToWorld);geometry.computeBoundingBox();all.union(geometry.boundingBox);
   const material=new THREE.MeshStandardMaterial({color:cortexColor,roughness:.74,metalness:0,transparent:false,opacity:1,side:THREE.FrontSide});
   const outward=new THREE.Vector3(),va=new THREE.Vector3(),vb=new THREE.Vector3(),vc=new THREE.Vector3(),positions=geometry.attributes.position,index=geometry.index;
   for(let i=0;i<index.count;i+=3){va.fromBufferAttribute(positions,index.getX(i));vb.fromBufferAttribute(positions,index.getX(i+1)).sub(va);vc.fromBufferAttribute(positions,index.getX(i+2)).sub(va);outward.add(vb.cross(vc));}
   if(outward.lengthSq()<1e-12)outward.set(part.hemisphere==='left'?-1:1,0,0);outward.normalize();
   geometry.computeBoundingSphere();
   const mesh=new THREE.Mesh(geometry,material);mesh.userData={id:part.id,name:part.name,hemisphere:part.hemisphere,color:cortexColor,outward,center:geometry.boundingBox.getCenter(new THREE.Vector3())};brain.add(mesh);parcels.push(mesh);
  }
  const center=all.getCenter(new THREE.Vector3());
  for(const m of parcels){m.geometry.translate(-center.x,-center.y,-center.z);m.userData.center.sub(center);}
  brain.updateMatrixWorld(true);manifest.sort((a,b)=>a.gene.localeCompare(b.gene));
  expressionPanel=new ExpressionPanel(expression,manifest,gene=>{currentGene=gene;if(mode==='protein'&&!gene)returnBrain();updateMeta();updateVRLabel();if(mode==='protein'&&gene)loadProtein();},ranking);
  document.body.classList.add('expression-ready');const initial=parcels.find(x=>x.userData.name==='postcentral'&&x.userData.hemisphere==='right');chooseRegion(initial,false);showBrainOrientation();$('loading').hidden=true;camera.position.copy(defaultCamera());
  window.neuroatlas={getState:()=>({mode,selectedRegion:selected?pretty(selected):null,currentGene,parcels:parcels.length,proteins:manifest.length,molecularObjects:molecule.children.length,brainVisible:brain.visible,busy,regionGeneCount:expressionPanel?.records.length||0,expressionMatch:expressionPanel?.region?.match||null}),selectRegion:name=>{const p=parcels.find(x=>x.userData.name===name);if(p)chooseRegion(p);},enterProtein,returnBrain};
 }catch(e){$('loading').hidden=false;$('loading').textContent='Could not load the model: '+e.message;console.error(e);}
}
init();renderer.setAnimationLoop(()=>{if(tween&&!renderer.xr.isPresenting){const t=Math.min((performance.now()-tween.start)/tween.duration,1),s=t*t*(3-2*t);camera.position.lerpVectors(tween.from,tween.to,s);controls.target.lerpVectors(tween.tf,tween.tt,s);if(t===1){const done=tween.done;tween=null;done?.();}}if(!renderer.xr.isPresenting)controls.update();renderer.render(scene,camera);});
